package net.minecraft.core;public record BlockPos(int x,int y,int z){public int getX(){return x;}public int getY(){return y;}public int getZ(){return z;}public BlockPos offset(int a,int b,int c){return new BlockPos(x+a,y+b,z+c);}public BlockPos below(){return offset(0,-1,0);}public long asLong(){return ((long)x & 0x3ffffffL)<<38|((long)z & 0x3ffffffL)<<12|((long)y & 0xfffL);}public static BlockPos of(long l){return new BlockPos((int)(l>>38),(int)(l<<52>>52),(int)(l<<26>>38));}}